  if(task.context.sourceSupportRepair&&sourceRepair)return {text:JSON.stringify({complete:true,edits:[{old:'该文献证明结果适用于所有场景。[source:r1]',new:'“'+source.slice(0,20)+'”。[source:r1]',evidence:{sourceId:'r1',quote:source.slice(0,20)}}]}),usage:{input:100,output:100},costUsd:.001,trace:[{tool:'read_material',status:'completed',materialId:'r1',offset:0,limit:6000}]};
  const result=response(task);
