  if(sourceRepair&&task.context.unit.chapterId==='c1'&&!task.context.completionRepairPass){const body=JSON.parse(result.text);body.text='该文献证明结果适用于所有场景。[source:r1]'+body.text;result.text=JSON.stringify(body);}
  if(!task.context.unit.frontMatter&&!task.context.unit.personalMatter){const body=JSON.parse(result.text);body.text=task.context.unit.chapterTitle+'的论述范围。'+body.text;result.text=JSON.stringify(body);}
  if(task.context.acknowledgementMode==='general'){const body=JSON.parse(result.text);body.text='谨向本文所引用公开文献的作者及阅读本文的读者致谢。本文对既有公开研究的梳理依照所提供资料完成，相关观点与引用由作者核对确认。'.repeat(3);result.text=JSON.stringify(body);}
