test('review batch reuse requires identical entire inputs, known cost and fresh evidence validation',async()=>{
 const {reviewBatchReuseKey,reusableReviewBatch}=await import('../backend/thesis-worker.mjs');const args={task:{skill:'writing-review',context:{evidence:'原句'},materials:[{id:'m',text:'材料'}]},snapshot:{requirements:{style:'A'},materials:[{id:'m',text:'资料',confirmed:true}],references:[{id:'r',title:'题目'}]},chapters:[{id:'c',title:'结果',text:'正文',figures:[]}],settings:{engine:'sdk',model:'m',version:'v1',maxTurns:4,maxOutputTokens:2048,timeoutMs:60000,maxCostUsd:.5}};const key=reviewBatchReuseKey(args),row=JSON.stringify({reuseKey:key,costKnown:true,text:'合成结果',trace:[{tool:'read_material',status:'completed'}],usage:{input:12,output:8}}),valid=async result=>({valid:result.trace?.[0]?.status==='completed'});
 assert.ok(await reusableReviewBatch([{result:row}],key,valid));assert.equal(await reusableReviewBatch([{result:row}],key,async()=>({valid:false})),null);assert.equal(await reusableReviewBatch([{result:JSON.stringify({...JSON.parse(row),costKnown:false})}],key,valid),null);assert.equal(await reusableReviewBatch([{result:JSON.stringify({...JSON.parse(row),usage:null})}],key,valid),null);assert.equal(await reusableReviewBatch([{result:'broken'}],key,valid),null);
 for(const changed of [{...args,chapters:[{...args.chapters[0],text:'正文改'}]},{...args,chapters:[{...args.chapters[0],figures:[{id:'f'}]}]},{...args,snapshot:{...args.snapshot,materials:[{id:'m',text:'资料改',confirmed:true}]}},{...args,snapshot:{...args.snapshot,references:[{id:'r',title:'新题目'}]}},{...args,snapshot:{...args.snapshot,requirements:{style:'B'}}},{...args,settings:{...args.settings,model:'other'}},{...args,validatorVersion:'a-new-deployment-version'}])assert.notEqual(reviewBatchReuseKey(changed),key);assert.equal(reviewBatchReuseKey({...args,validatorVersion:null}),null);
 const normalized=await reusableReviewBatch([{result:row}],key,async()=>({valid:true,normalizedText:'核验后的结果',normalizedTrace:[{tool:'read_material'}]}));assert.equal(normalized.text,'核验后的结果');assert.equal(normalized.trace[0].tool,'read_material');
 const outsideBatch={...args,chapters:[...args.chapters,{id:'outside',title:'附加章节',text:'不在当前批次',sourceIds:['r'],figures:[]}]},outsideKey=reviewBatchReuseKey(outsideBatch);assert.notEqual(reviewBatchReuseKey({...outsideBatch,chapters:[args.chapters[0],{...outsideBatch.chapters[1],title:'更改标题'}]}),outsideKey);assert.notEqual(reviewBatchReuseKey({...outsideBatch,chapters:[args.chapters[0],{...outsideBatch.chapters[1],sourceIds:['other']}]}),outsideKey);
});

test('section-scoped review selects uniquely anchored findings without dropping ambiguous cross-section issues',()=>{
 const findings=[{quote:'第一节唯一问题'},{quote:'第二节唯一问题'},{quote:'共同的表述'},{quote:'跨越分节边界的说法'}];
 const units=[{completion:{originalText:'第一节唯一问题。共同的表述。跨越分节',findings:structuredClone(findings)}},{completion:{originalText:'第二节唯一问题。共同的表述。边界的说法',findings:structuredClone(findings)}}];scopeCompletionFindings(units);
 assert.deepEqual(units[0].completion.findings.map(x=>x.quote),['第一节唯一问题','共同的表述','跨越分节边界的说法']);
 assert.deepEqual(units[1].completion.findings.map(x=>x.quote),['第二节唯一问题','共同的表述','跨越分节边界的说法']);
 const many=[...Array.from({length:8},(_,i)=>({quote:'其他节事项'+i})),{quote:'本节需要修改'}],parts=[{completion:{originalText:'本节需要修改',findings:structuredClone(many)}},{completion:{originalText:many.slice(0,8).map(x=>x.quote).join('。'),findings:structuredClone(many)}}];scopeCompletionFindings(parts);assert.deepEqual(parts[0].completion.findings.map(x=>x.quote),['本节需要修改']);
});

