test('review reuse candidates are constrained to account, run, prior attempt, exact task and final checks',async()=>{
 const {eligibleReviewCheckpoints}=await import('../backend/thesis-worker.mjs');const {DatabaseSync}=await import('node:sqlite');const db=new DatabaseSync(':memory:');
 try{
  db.exec('CREATE TABLE thesis_runs(id TEXT,user_id TEXT); CREATE TABLE thesis_review_checkpoints(run_id TEXT,attempt INTEGER,unit_id TEXT,task_hash TEXT,result TEXT,created_at TEXT)');
  db.prepare('INSERT INTO thesis_runs VALUES(?,?)').run('run-1','owner');db.prepare('INSERT INTO thesis_runs VALUES(?,?)').run('run-2','other');
  const put=(run,attempt,unit,hash,result)=>db.prepare('INSERT INTO thesis_review_checkpoints VALUES(?,?,?,?,?,?)').run(run,attempt,unit,hash,result,String(attempt));
  put('run-1',1,'completion-quality-0::quality-review::1','hash','quality');put('run-1',1,'completion-quality-0::supplement-final::1','hash','supplement');
  put('run-1',3,'completion-quality-0::quality-review::1','hash','future');put('run-1',1,'completion-quality-0::quality-review::1','other-hash','different task');
  put('run-1',1,'completion-quality-0::supplement-materials::1','hash','precheck');put('run-1',1,'completion-quality-0::repair::1','hash','repair');put('run-2',1,'completion-quality-0::quality-review::1','hash','other run');
  const select=userId=>eligibleReviewCheckpoints(db,{runId:'run-1',userId,attempt:2,taskHash:'hash'}).map(row=>row.result).sort();
  assert.deepEqual(select('owner'),['quality','supplement']);assert.deepEqual(select('other'),[]);
 }finally{db.close();}
});

