test('a citation reattribution warning preserves the result for review without retrying an incompatible source repair',async t=>{
 const f=fullFixture(t,{repair:true,sourceRepair:true,persistentFinding:true});f.pay();const original=f.config.agentTaskRunner;f.config.agentTaskRunner=async args=>{const out=await original(args);if(args.task.skill==='writing-review'){const value=JSON.parse(out.text);for(const finding of value.findings||[])if(finding.category==='source_support')finding.suggestion='将来源标记改为自设算例材料，或删除该处文献标记，由作者核对后确认。';out.text=JSON.stringify(value);}return out;};let item=await completeSaved(f);await submitFull(f,item);await f.worker.tick();item=f.get(item.id);
 assert.equal(item.job.status,'completed',item.job.error);assert.equal(f.allCalls.some(task=>task.context.sourceSupportRepair),false);assert.match(item.chapters.find(row=>row.id==='c1').text,/该文献证明结果适用于所有场景。\[source:r1\]/);assert.ok(item.quality.reviews.flatMap(row=>row.findings).some(row=>row.category==='source_support'&&/自设算例材料/.test(row.suggestion)));assert.notEqual(item.completionReview.status,'ready');assert.notEqual(item.completionReview.status,'confirmed');assert.equal(f.billing.balance(f.user.id).held,0);
});
test('failed source correction retains the original and releases its reservation',async t=>{
 const f=fullFixture(t,{repair:true,sourceRepair:true});f.pay();const orig=f.config.agentTaskRunner;f.config.agentTaskRunner=async args=>{const out=await orig(args);if(args.task.context.sourceSupportRepair)out.trace=[];return out;};let item=await completeSaved(f),before=item.chapters.map(c=>({id:c.id,text:c.text,version:c.version}));await submitFull(f,item);await f.worker.tick();item=f.get(item.id);assert.equal(item.job.status,'failed');assert.deepEqual(item.chapters.map(c=>({id:c.id,text:c.text,version:c.version})),before);assert.equal(f.billing.balance(f.user.id).balance,200);assert.equal(f.billing.balance(f.user.id).held,0);const rows=f.db.prepare("SELECT trace FROM thesis_checkpoints WHERE run_id=?").all(item.job.id).flatMap(r=>JSON.parse(r.trace||'[]'));const diagnostic=rows.find(r=>r.stage==='completion_repair_failed');assert.equal(diagnostic.repairType,'source_support');assert.equal(diagnostic.errorCode,'invalid_review_output');assert.doesNotMatch(JSON.stringify(diagnostic),/论文|实验|source:/);
});
test('failed source correction can resume from checkpoints and settle only once',async t=>{
 const f=fullFixture(t,{repair:true,sourceRepair:true});f.pay();const orig=f.config.agentTaskRunner;let failed=false;f.config.agentTaskRunner=async args=>{const out=await orig(args);if(args.task.context.sourceSupportRepair&&!failed){failed=true;out.trace=[];}return out;};let item=await completeSaved(f);await submitFull(f,item);await f.worker.tick();item=f.get(item.id);assert.equal(item.job.status,'failed');assert.equal(f.billing.balance(f.user.id).balance,200);const quote=await f.request('/api/theses/'+item.id+'/quote',{version:item.version,action:'resume'});await f.request('/api/theses/'+item.id+'/resume',{version:item.version,clientKey:randomUUID(),billingToken:quote.token,consent:true});await f.worker.tick();const done=f.get(item.id);assert.equal(done.job.status,'completed',done.job.error);assert.equal(f.billing.balance(f.user.id).balance,190);assert.equal(f.billing.balance(f.user.id).held,0);assert.equal(f.db.prepare("SELECT count(*) n FROM billing_events e JOIN billing_reservations r ON r.id=e.reservation_id WHERE r.job_id=? AND e.kind='settle'").get(done.job.id).n,1);
});

test('resumed completion reuses only unchanged validated terminal review batches and settles once',async t=>{
 const f=fullFixture(t,{repair:true,sourceRepair:true});f.pay();const orig=f.config.agentTaskRunner;let failed=false;
 f.config.agentTaskRunner=async args=>{const out=await orig(args);if(args.task.context.sourceSupportRepair&&!failed){failed=true;out.trace=[];}return out;};
 let item=await completeSaved(f);await submitFull(f,item);await f.worker.tick();item=f.get(item.id);assert.equal(item.job.status,'failed');
 const firstCalls=f.allCalls.length, firstReviews=f.allCalls.filter(task=>task.skill==='writing-review'&&task.context.operation!=='supplement-check').length;
 const before=f.db.prepare('SELECT provider_calls FROM thesis_runs WHERE id=?').get(item.job.id).provider_calls;
 const quote=await f.request('/api/theses/'+item.id+'/quote',{version:item.version,action:'resume'});await f.request('/api/theses/'+item.id+'/resume',{version:item.version,clientKey:randomUUID(),billingToken:quote.token,consent:true});await f.worker.tick();const done=f.get(item.id);assert.equal(done.job.status,'completed',done.job.error);
 const resumed=f.allCalls.slice(firstCalls), reviews=resumed.filter(task=>task.skill==='writing-review'&&task.context.operation!=='supplement-check');
 assert.ok(firstReviews>=1);assert.equal(reviews.length,firstReviews,'unchanged prior batches are reused; only the changed manuscript is reviewed again');
 assert.ok(resumed.some(task=>task.context.operation==='supplement-check'&&task.context.phase==='materials'),'pre-completion check is not reused');
 assert.equal(f.db.prepare('SELECT provider_calls FROM thesis_runs WHERE id=?').get(done.job.id).provider_calls-before,resumed.length);
 assert.equal(f.billing.balance(f.user.id).balance,190);assert.equal(f.billing.balance(f.user.id).held,0);
 assert.equal(f.db.prepare("SELECT count(*) n FROM billing_events e JOIN billing_reservations r ON r.id=e.reservation_id WHERE r.job_id=? AND e.kind='settle'").get(done.job.id).n,1);
});

