test('failed source repair records only bounded rejection categories and no material text',async t=>{
 const f=fullFixture(t,{repair:true,sourceRepair:true});f.pay();const original=f.config.agentTaskRunner;f.config.agentTaskRunner=async args=>{if(args.task.context.sourceSupportRepair){const error=Object.assign(Error('synthetic private content must not persist'),{code:'turn_limit',usage:{input:30,output:10},costUsd:.001});Object.defineProperty(error,'agentTrace',{value:[{tool:'submit_writing_output',status:'completed',validation:{code:'source_repair_read',rule:'private source passage'}},{tool:'submit_writing_output',status:'completed',validation:{code:'source_repair_read'}},{tool:'submit_writing_output',status:'completed',validation:{code:'source_repair_quotation'}},{tool:'submit_writing_output',status:'completed',validation:{code:'private_source_passage'}}]});throw error;}return original(args);};
 let item=await completeSaved(f);await submitFull(f,item);await f.worker.tick();item=f.get(item.id);assert.equal(item.job.status,'failed');const traces=f.db.prepare('SELECT trace FROM thesis_checkpoints WHERE run_id=?').all(item.job.id).flatMap(row=>JSON.parse(row.trace||'[]')),diagnostic=traces.find(row=>row.stage==='completion_repair_failed');assert.equal(diagnostic.repairType,'source_support');assert.equal(diagnostic.errorCode,'turn_limit');assert.deepEqual(diagnostic.rejections,{source_repair_read:2,source_repair_quotation:1});assert.doesNotMatch(JSON.stringify(diagnostic),/private|passage/);assert.equal(f.billing.balance(f.user.id).held,0);assert.equal(f.billing.balance(f.user.id).balance,200);
});

test('a completed no-op final revision releases reserved credits',async t=>{
 const runner=async({task})=>{
  if(task.context.operation==='supplement-check')return {text:JSON.stringify({items:task.context.chapters.map(row=>({id:row.id,status:'sufficient',requirement:'核对研究依据',reason:'合成资料已核对。',manuscriptQuote:row.text.slice(0,30),evidence:[{sourceId:task.context.evidence[0].id,quote:task.context.evidence[0].text.slice(0,30)}],missing:[],checkedFigureIds:(row.figures||[]).map(figure=>figure.id)}))}),usage:{input:100,output:100},costUsd:.001};
  if(task.skill==='writing-review')return {text:JSON.stringify({complete:true,findings:[],limitations:[]}),usage:{input:100,output:100},costUsd:.001};
  const text=task.context.revision?.originalExcerpt??task.context.originalAcknowledgement??'',ids=[...new Set([...text.matchAll(/\[source:([^\]]+)\]/g)].map(match=>match[1]))];return {text:JSON.stringify({text,source_ids:ids,missing_evidence:[],complete:true,figures:[],draft:false}),usage:{input:100,output:300},costUsd:.001,finishReason:'end_turn',trace:ids.map(materialId=>({tool:'read_material',status:'completed',materialId}))};
 };
 const f=fixture(t,{thesisContinuousEnabled:true,supplementCheckEnabled:true,writingQualityEnabled:true,citationVerifier:{verify:async()=>({version:1,status:'completed',items:[],summary:{},limitations:[]})},agentTaskRunner:runner});f.pay();let item=await completeSaved(f);
 for(const chapter of item.chapters){if(chapter.id==='refs'){const {compileThesisReferences}=await import('../backend/thesis-model.mjs');item=await f.save(item,chapter.id,compileThesisReferences(item.snapshot,['r1']));}else if(/致谢/.test(chapter.title)){item=await f.save(item,chapter.id,'感谢阅读本文的读者与所引用的公开研究作者。'.repeat(15));}else if(/^(?:摘要|Abstract)$/i.test(chapter.title)){const unit={chapterId:chapter.id,title:chapter.title,chapterTitle:chapter.title,targetWords:chapter.title==='Abstract'?250:400,frontMatter:chapter.title==='Abstract'?'abstract_en':'abstract_zh'};item=await f.save(item,chapter.id,JSON.parse(response({context:{unit},materials:[]}).text).text);}}
 await submitFull(f,item);await f.worker.tick();item=f.get(item.id);assert.equal(item.job.status,'completed',item.job.error);assert.equal(item.quality.status,'completed');assert.equal(item.quality.coverage.complete,true);assert.equal(item.quality.supplementCheck.coverage.complete,true);assert.equal(item.completionReview.billingStatus,'released');assert.equal(f.billing.balance(f.user.id).balance,200);assert.equal(f.billing.balance(f.user.id).held,0);
});

