 const f=fullFixture(t);let item=await completeSaved(f);const updatedSnapshot=structuredClone(item.snapshot);updatedSnapshot.references[0].doi='10.1234/TEST';updatedSnapshot.references.push({...updatedSnapshot.references[0],id:'r2',doi:'https://doi.org/10.1234/test'});item=(await f.request('/api/theses/'+item.id,{version:item.version,snapshot:updatedSnapshot})).item;
 const original=f.config.agentTaskRunner;f.config.agentTaskRunner=async args=>{const result=await original(args);if(args.task.skill==='thesis-section'&&!args.task.context.unit.frontMatter&&!args.task.context.unit.personalMatter){const body=JSON.parse(result.text);body.text+='[source:r2]';body.source_ids.push('r2');result.text=JSON.stringify(body);result.trace.push({tool:'read_material',status:'completed',materialId:'r2'});}return result;};
 await submitFull(f,item);await f.worker.tick();const finished=f.get(item.id);assert.equal(finished.job.status,'completed',finished.job.error);assert.ok(finished.completionReview.issues.some(row=>/DOI 相同/.test(row.text)));assert.notEqual(finished.completionReview.status,'ready');assert.notEqual(finished.completionReview.status,'confirmed');const body=finished.chapters.find(row=>row.id==='c1').text;assert.match(body,/\[source:r1\]/);assert.match(body,/\[source:r2\]/);assert.equal(finished.snapshot.references.length,2);
